    pub fn from_stream(
        stream: UnixStream,
        peer: AgentdFinalUseIssuerPeer,
        timeout: Duration,
    ) -> Result<Self, AgentdFinalUseIssuerError> {
        if peer.pid == 0 || peer.pid > i32::MAX as u32 || timeout.is_zero() || timeout > MAX_TIMEOUT
        {
            return Err(AgentdFinalUseIssuerError::InvalidConfiguration);
        }
        validate_peer(&stream, peer)?;
        stream.set_nonblocking(false).map_err(io_error)?;
        Ok(Self {
            stream: Mutex::new(Some(stream)),
            timeout,
            protected_root: None,
            phase: None,
        })
    }

    pub(crate) fn into_same_actor_phase(
        mut self,
        gate: &std::sync::Arc<crate::same_actor_q24_phase_gate::SameActorPhaseGate>,
    ) -> Result<Self, AgentdFinalUseIssuerError> {
        let mut closing = crate::same_actor_q24_phase_gate::CloseSameActorPhaseOnDrop::new(gate);
        if self.phase.is_some()
            || self
                .protected_root
                .as_ref()
                .is_none_or(|root| root.end != gate.deadline().instant())
        {
            return Err(AgentdFinalUseIssuerError::InvalidConfiguration);
        }
        let stream = self
            .stream
            .get_mut()
            .map_err(|_| AgentdFinalUseIssuerError::ChannelClosed)?
            .as_ref()
            .ok_or(AgentdFinalUseIssuerError::ChannelClosed)?;
        let phase = gate
            .retain_required_original_stream(stream)
            .map_err(|_| AgentdFinalUseIssuerError::Unavailable)?;
        phase
            .require_open()
            .map_err(|_| AgentdFinalUseIssuerError::Unavailable)?;
        self.phase = Some(phase);
        closing.disarm();
        Ok(self)
    }

    pub fn request_grant(
        &self,
        binding: &FinalUseBinding,
    ) -> Result<SignedFinalUseGrant, AgentdFinalUseIssuerError> {
        let mut phase_close = self
            .phase
            .as_ref()
            .map(super::same_actor_q24_phase_gate::RequiredSameActorPhaseChannel::failure_scope);
        if let Some(phase) = &self.phase {
            phase
                .require_open()
                .map_err(|_| AgentdFinalUseIssuerError::Unavailable)?;
        }

        if binding.subject_id.len() > 128 || binding.destination_id.len() > 128 {
            return Err(AgentdFinalUseIssuerError::InvalidGrant);
        }
        let request = serde_json::to_vec(&IssuerRequest {
            schema_version: SCHEMA_VERSION,
            operation: OPERATION,
            binding,
        })
        .map_err(|_| AgentdFinalUseIssuerError::InvalidGrant)?;
        if request.is_empty() || request.len() > MAX_REQUEST_BYTES {
            return Err(AgentdFinalUseIssuerError::InvalidGrant);
        }
        self.exchange_guarded(|stream, deadline| exchange(stream, &request, binding, deadline))?
            .ok_or(AgentdFinalUseIssuerError::Denied)
            .inspect(|_| {
                if let Some(closing) = &mut phase_close {
                    closing.disarm();
                }
            })
    }

    fn exchange_guarded<T>(
        &self,
        exchange: impl FnOnce(&mut UnixStream, Instant) -> Result<T, AgentdFinalUseIssuerError>,
    ) -> Result<T, AgentdFinalUseIssuerError> {
        let mut phase_close = self
            .phase
            .as_ref()
            .map(super::same_actor_q24_phase_gate::RequiredSameActorPhaseChannel::failure_scope);
        if let Some(phase) = &self.phase {
            phase
                .require_open()
                .map_err(|_| AgentdFinalUseIssuerError::Unavailable)?;
        }
        let mut slot = self.stream.try_lock().map_err(|error| match error {
            std::sync::TryLockError::WouldBlock => AgentdFinalUseIssuerError::Busy,
            std::sync::TryLockError::Poisoned(_) => AgentdFinalUseIssuerError::ChannelClosed,
        })?;
        let mut stream = slot
            .take()
            .ok_or(AgentdFinalUseIssuerError::ChannelClosed)?;
        let deadline = (Instant::now() + self.timeout).min(
            self.protected_root
                .as_ref()
                .map_or_else(|| Instant::now() + self.timeout, |root| root.end),
        );
        let result = (|| {
            self.check_root()?;
            remaining(deadline)?;
            let response = exchange(&mut stream, deadline)?;
            self.check_root()?;
            remaining(deadline)?;
            if let Some(phase) = &self.phase {
                phase
                    .require_open()
                    .map_err(|_| AgentdFinalUseIssuerError::Unavailable)?;
            }
            Ok(response)
        })();
        match result {
            Ok(response) => {
                *slot = Some(stream);
                if let Some(phase) = &self.phase {
                    phase
                        .require_open()
                        .map_err(|_| AgentdFinalUseIssuerError::Unavailable)?;
                }
                if let Some(closing) = &mut phase_close {
                    closing.disarm();
                }
                Ok(response)
            }
            Err(error) => {
                let _ = stream.shutdown(Shutdown::Both);
                Err(error)
            }
        }
    }



    pub(crate) fn retire_original_root_grant_purpose(
        &self,
        intent: &crate::same_actor_q24_deployment::OriginalRootRetirementIntent,
    ) -> Result<(), crate::AgentdError> {
        let phase = self.phase.as_ref().ok_or_else(|| {
            crate::AgentdError::GenerationFenced(                                .into())
        })?;
        let mut closing = phase.failure_scope();
        intent.require_original_gate(phase.gate())?;
        let slot = self.stream.try_lock().map_err(|_| {
            crate::AgentdError::GenerationFenced(                                    .into())
        })?;
        if slot.is_none() || self.protected_root.is_none() {
            return Err(crate::AgentdError::GenerationFenced(
                                                                .into(),
            ));
        }
        self.check_root().map_err(|error| {
            crate::AgentdError::Protocol(format!(                              ))
        })?;
        phase.shutdown_original_after_root_intent(intent)?;
        self.check_root().map_err(|error| {
            crate::AgentdError::Protocol(format!(                              ))
        })?;
        intent.require_original_gate(phase.gate())?;
        closing.disarm();
        Ok(())
    }

    fn check_root(&self) -> Result<(), AgentdFinalUseIssuerError> {
        if let Some(root) = &self.protected_root {
            root.channel
                .check_peer_lifetime()
                .map_err(|_| AgentdFinalUseIssuerError::PeerDenied)?;
        }
        Ok(())
    }
