            std::sync::TryLockError::Poisoned(_) => AgentdFinalUseIssuerError::ChannelClosed,
        })?;
        let mut stream = slot
            .take()
            .ok_or(AgentdFinalUseIssuerError::ChannelClosed)?;
        let deadline = (Instant::now() + self.timeout).min(
            self.protected_root
                .as_ref()
                .map_or_else(|| Instant::now() + self.timeout, |root| root.end),
        );
        let result = (|| {
            self.check_root()?;
            remaining(deadline)?;
            let response = exchange(&mut stream, deadline)?;
            self.check_root()?;
            remaining(deadline)?;
            if let Some(phase) = &self.phase {
                phase
                    .require_open()
                    .map_err(|_| AgentdFinalUseIssuerError::Unavailable)?;
            }
            Ok(response)
        })();
        match result {
            Ok(response) => {
                *slot = Some(stream);
                if let Some(phase) = &self.phase {
                    phase
                        .require_open()
                        .map_err(|_| AgentdFinalUseIssuerError::Unavailable)?;
                }
                if let Some(closing) = &mut phase_close {
                    closing.disarm();
                }
                Ok(response)
            }
            Err(error) => {
                let _ = stream.shutdown(Shutdown::Both);
                Err(error)
            }
        }
    }



